INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(24401, 'Luke 13:10', 'Luke', 13, 10, '&nbsp;د سبت په ورځ عيسىٰ په يوه عبادتخانه کښې تعليم ورکولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24402, 'Luke 13:11', 'Luke', 13, 11, '&nbsp;نو يوه ښځه وه چې د اتلسو کالو راسې پيريانو نيولې وه او بې‌حاله کړې يې وه او ملا يې ورله داسې کږه کړې وه چې هيڅکله نېغه نۀ شوه ودرېدلے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24403, 'Luke 13:12', 'Luke', 13, 12, '&nbsp;کله چې عيسىٰ هغه وليده نو راوې بلله او ورته يې وفرمائيل، ”اے مورې، تۀ د خپل تکليف نه آزاده شوې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24404, 'Luke 13:13', 'Luke', 13, 13, '&nbsp;او بيا يې خپل لاسونه په هغې کېښودل، نو بيا سمدستى هغه نېغه ودرېده او د خُدائ پاک ثنا يې ووئيله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24405, 'Luke 13:14', 'Luke', 13, 14, '&nbsp;خو د عبادتخانې مشر د سبت په ورځ د عيسىٰ د روغولو په عمل ډېر خفه شو او موجودو خلقو ته يې ووئيل چې، ”د کار دپاره شپږ ورځې مقرر شوې دى. په هغو ورځو کښې د شفا حاصلولو دپاره راځئ خو د سبت په ورځ مۀ راځئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24406, 'Luke 13:15', 'Luke', 13, 15, '&nbsp;خو مالِک هغۀ ته جواب ورکړو او وې فرمائيل، ”اے مُنافقانو، په تاسو کښې يو کس هم داسې شته څوک چې د سبت په ورځ خپل غوائى يا خر د اخور نه نۀ پرانيزى او اوبو له يې نۀ بوځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24407, 'Luke 13:16', 'Luke', 13, 16, '&nbsp;او دلته دا مور د اِبراهيم لور ده چې د اتلسو کالو راسې شېطان قېد کړې وه ولې دا ښۀ خبره نۀ ده چې د سبت په ورځ هغه د دې قېد نه آزاده شى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24408, 'Luke 13:17', 'Luke', 13, 17, '&nbsp;د هغۀ په دې وينا د هغۀ ټول مخالفين شرمنده شول او خلقو د دۀ په دې عجيبه کارونو کولو ډېره خوشحالى وکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24409, 'Luke 13:18', 'Luke', 13, 18, '&nbsp;بيا عيسىٰ وفرمائيل چې، ”د خُدائ پاک بادشاهى په څۀ شان ده؟ زۀ د خُدائ بادشاهى د څۀ سره بيان کړم؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24410, 'Luke 13:19', 'Luke', 13, 19, '&nbsp;دا د شړشمو د هغه تخم په شان ده چې يو سړى راواخستو او په خپل باغ کښې يې وکَرلو او چې شړشم راوټوکېدل نو لکه د ونې په رنګ لوئ شول نو مارغان راتلل او په څانګو کښې به يې جالې جوړولې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24411, 'Luke 13:20', 'Luke', 13, 20, '&nbsp;هغۀ بيا دا وفرمائيل، ”زۀ د خُدائ پاک بادشاهى د څۀ سره بيان کړم؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24412, 'Luke 13:21', 'Luke', 13, 21, '&nbsp;دا د خمبيرې په شان ده چې يوې ښځې راواخسته او په درېو قلپو اوړو کښې يې ګډه کړه نو بيا هغه درې واړه خمبيره شول.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24413, 'Luke 13:22', 'Luke', 13, 22, '&nbsp;کله چې عيسىٰ يروشلم ته تلو نو په کلو او ښاريو تېرېدو او په تلو تلو کښې يې خلقو ته ځائ په ځائ تعليم ورکولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24414, 'Luke 13:23', 'Luke', 13, 23, '&nbsp;يو کس ترېنه تپوس وکړو، ”مالِکه، ولې صرف يو څو تنه به بچ شى؟“ نو هغۀ ورته په جواب کښې وفرمائيل،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24415, 'Luke 13:24', 'Luke', 13, 24, '&nbsp;”کوشش وکړئ چې په تنګه دروازه ورداخل شئ، ځکه چې زۀ درته دا وايم چې ډېر به د داخلېدو کوشش کوى خو داخلېدلے به نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24416, 'Luke 13:25', 'Luke', 13, 25, '&nbsp;خو چې کله د کور مالِک راپاڅى او د خپل کور دروازه بنده کړى کۀ تاسو بهر ولاړ يئ او دروازه ټکوئ او مِنت کوئ چې مالِکه، مونږ ته دروازه کولاو کړه. خو هغه به جواب درکړى چې زۀ خو تاسو نۀ پېژنم چې تاسو څوک يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24417, 'Luke 13:26', 'Luke', 13, 26, '&nbsp;نو بيا به تاسو داسې وايئ چې، مونږ خو تا سره يو ځائ خوړل څښل کړى دى او تا زمونږ په کوڅو کښې تعليم ورکولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24418, 'Luke 13:27', 'Luke', 13, 27, '&nbsp;خو هغه به بيا درته داسې ووائى چې، زۀ خو تاسو د سره نۀ پېژنم چې د کوم ځائ نه راغلى يئ. تاسو ټول بدکاران زما نه ورک شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24419, 'Luke 13:28', 'Luke', 13, 28, '&nbsp;بيا به هلته تاسو ووينئ چې اِبراهيم، اِسحاق او يعقوب او نور ټول پېغمبران د خُدائ پاک په بادشاهۍ کښې دى خو تاسو به هغه ځائ ته غورزولے شئ چرته چې ژړا وير او د غاښونو چيچل وى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24420, 'Luke 13:29', 'Luke', 13, 29, '&nbsp;د دُنيا د هر ګوټ نه به خلق د خُدائ پاک د بادشاهۍ مېلمستيا ته راځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24421, 'Luke 13:30', 'Luke', 13, 30, '&nbsp;بې‌شکه يو څو کسان چې په کښې آخر دى، هغوئ به د ټولو نه اول شى او يو څو کسان چې اول دى هغوئ به د ټولو نه آخر شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24422, 'Luke 13:31', 'Luke', 13, 31, '&nbsp;په هم دغه وخت يو څو فريسيان راغلل او عيسىٰ ته يې ووئيل چې، ”تۀ د دې ځايه ووځه او لاړ شه ځکه چې هيروديس ستا د وژلو نيت کړے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24423, 'Luke 13:32', 'Luke', 13, 32, '&nbsp;خو هغۀ جواب ورکړو، ”لاړ شئ او هغه ګيدړ ته ووايئ چې واوره. نن او سبا به زۀ پيريان وباسم او د شفا ورکولو کار به جارى ساتم او په درېمه ورځ به خپل کار سر ته ورسوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24424, 'Luke 13:33', 'Luke', 13, 33, '&nbsp;بيا هم ما ته پکار دى چې زۀ نن او سبا په خپله لاره تلل وکړم او په بله ورځ هم، ځکه چې د نبى دپاره دا ناممکنه ده چې هغه دې د يروشلم نه بغېر په بل ځائ کښې مړ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24425, 'Luke 13:34', 'Luke', 13, 34, '&nbsp;اے يروشلمه، اے د يروشلم ښاريې چې تۀ نبيان وژنې او رسولان سنګساروې کوم چې تا ته رالېږلے شوى دى. ما څو ځله دا ارمان وکړو چې ستا بچى راغونډ کړم، داسې لکه چې چرګه خپل بچى د وزرو لاندې راغونډوى، خو تا دا نۀ غوښتل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24426, 'Luke 13:35', 'Luke', 13, 35, '&nbsp;وګوره، ستا کور تا ته وران ويجاړ پاتې کيږى او زۀ تا ته دا وايم چې تۀ به ما تر هغې په سترګو ونۀ وينې ترڅو چې تۀ دا ونۀ وائې چې، بختور دے هغه څوک چې د مالِک خُدائ په نوم راځى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24427, 'Luke 14:1', 'Luke', 14, 1, '&nbsp;د سبت په ورځ عيسىٰ د يو مشر فريسى په کور کښې روټۍ خوړلو له ورغلو او د خلقو په هغۀ نظر وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24428, 'Luke 14:2', 'Luke', 14, 2, '&nbsp;هلته يو سړے وو چې ورته د پړسوب بيمارى لګېدلې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24429, 'Luke 14:3', 'Luke', 14, 3, '&nbsp;عيسىٰ د شرعې د عالمانو او فريسيانو نه تپوس وکړو چې، ”د سبت په ورځ خلقو له شفا ورکول روا دى او کۀ نه؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24430, 'Luke 14:4', 'Luke', 14, 4, '&nbsp;هغوئ لاجوابه پاتې شُو نو عيسىٰ هغه سړے د لاسه ونيولو او شفا يې ورکړه او رُخصت يې کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24431, 'Luke 14:5', 'Luke', 14, 5, '&nbsp;بيا هغۀ هغوئ ته وفرمائيل، ”کۀ چرې د سبت په ورځ ستاسو زوئ يا څاروے په کوهى کښې پرېوځى، ولې تاسو به هغه سمدستى راونۀ باسئ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24432, 'Luke 14:6', 'Luke', 14, 6, '&nbsp;نو د هغوئ سره د دې خبرې هيڅ جواب نۀ وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24433, 'Luke 14:7', 'Luke', 14, 7, '&nbsp;کله چې عيسىٰ دا وکتل چې مېلمنو څنګه د عزت ځايونه کتل نو هغۀ هغوئ ته دا مِثال تير کړو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24434, 'Luke 14:8', 'Luke', 14, 8, '&nbsp;”کله چې تاسو څوک د وادۀ روټۍ ته وغواړى نو د عزت په ځائ مۀ کښېنئ. کېدے شى چې ستاسو نه څوک زيات عزتمند رابللے شوے وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24435, 'Luke 14:9', 'Luke', 14, 9, '&nbsp;نو کوربه به راشى او تاسو ته به ووائى چې دې سړى ته خپل ځائ پرېږده او بيا به تۀ په هغه وخت ډېر کچه شې کله چې تۀ د ټولو نه وروستو کښېنې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24436, 'Luke 14:10', 'Luke', 14, 10, '&nbsp;کله چې تا ته بلنه درکړے شى نو لاړ شه او د ټولو نه وروستو کښېنه ځکه چې کله چې کوربه راشى نو هغه به درته ووائى، زما آشنا، وړاندې راشه. نو ستا ټول ملګرى مېلمانۀ به ستا د هغه عزت تماشه وکړى، کوم چې تا ته درکړے شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24437, 'Luke 14:11', 'Luke', 14, 11, '&nbsp;ځکه چې هر هغه څوک چې ځان اوچتوى، هغه به عاجز کړے شى او هر هغه څوک چې ځان عاجز کړى، هغه به اوچت شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24438, 'Luke 14:12', 'Luke', 14, 12, '&nbsp;بيا عيسىٰ خپل کوربه ته وفرمائيل، ”هر کله چې تۀ د غرمې يا ماښام د روټۍ دپاره څوک راغواړې نو خپلو دوستانو، وروڼو، عزيزانو او اميرانو ګاونډيانو ته بلنه مۀ ورکوه ځکه چې هغوئ به هم تا ته بلنه درکړى او بدل به دې خلاص کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24439, 'Luke 14:13', 'Luke', 14, 13, '&nbsp;خو هر کله چې تۀ دعوت کوې نو غريبانان، شل ګوډ او ړاندۀ راوبله،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24440, 'Luke 14:14', 'Luke', 14, 14, '&nbsp;او دغه شان به تاسو برکت ومومئ ځکه چې هغوئ تاسو ته د بدل درکولو جوګه نۀ دى، خو د قيامت په ورځ به خُدائ پاک تاسو له د صادقانو سره اجر درکړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24441, 'Luke 14:15', 'Luke', 14, 15, '&nbsp;په دې خلقو کښې يو کس چې د عيسىٰ سره روټۍ ته ناست وو نو په دې خبرې اورېدو سره يې هغۀ ته ووئيل، ”بختور دى هغه څوک چې د خُدائ پاک د بادشاهۍ په مېلمستيا کښې ګډون وکړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24442, 'Luke 14:16', 'Luke', 14, 16, '&nbsp;عيسىٰ جواب ورکړو، ”يو سړى د يوې لوئ مېلمستيا بندوبست کړے وو او ګڼ خلق يې رابللى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24443, 'Luke 14:17', 'Luke', 14, 17, '&nbsp;د روټۍ په وخت هغۀ خپل نوکر رابللے شوو مېلمنو پسې ولېږلو او ورته يې ووئيل چې مهربانى وکړئ، روټۍ تياره ده راشئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24444, 'Luke 14:18', 'Luke', 14, 18, '&nbsp;خو هغوئ ټولو څۀ نه څۀ بهانه وکړه. وړومبى ووئيل، ما يوه ټوټه زمکه اخستې ده، زۀ ځم چې هغه وګورم. نو مهربانى وکړه زما عُذر قبول کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24445, 'Luke 14:19', 'Luke', 14, 19, '&nbsp;دوېم ووئيل چې، ما پينځۀ قلبې غوَيان اخستى دى، زۀ ځم چې هغوئ جوت کړم. نو مهربانى وکړه، زما عُذر قبول کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24446, 'Luke 14:20', 'Luke', 14, 20, '&nbsp;بل ووئيل، ما اوس اوس وادۀ کړے دے، په دې وجه درتلے نۀ شم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24447, 'Luke 14:21', 'Luke', 14, 21, '&nbsp;کله چې نوکر واپس شو نو دا هر څۀ يې خپل مالِک ته ووئيل. د کور مالِک په غصه شو او نوکر ته يې ووئيل چې زر د ښار کوڅو او بازارونو ته لاړ شه خواران، شل ګوډ او ړاندۀ راټول کړه او دلته يې راوله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24448, 'Luke 14:22', 'Luke', 14, 22, '&nbsp;نوکر ووئيل، صاحبه، ستا حکم په ځائ کړے شو خو بيا هم ځائ شته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24449, 'Luke 14:23', 'Luke', 14, 23, '&nbsp;نو مالِک ورته ووئيل چې لاړ شه او لويو لارو کوڅو ته ووځه او خلق په مِنت سره راوله چې زما کور د دوئ نه ډک شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24450, 'Luke 14:24', 'Luke', 14, 24, '&nbsp;خو دا درته وايم څوک چې اول رابللے شوى وُو په هغوئ کښې به يو تن هم دا روټۍ ونۀ څکى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24451, 'Luke 14:25', 'Luke', 14, 25, '&nbsp;اوس چې يوه لويه ګڼه د عيسىٰ سره جوړه شوې وه، هغۀ هغوئ ته مخ راواړولو او ورته يې وفرمائيل،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24452, 'Luke 14:26', 'Luke', 14, 26, '&nbsp;”هغه څوک چې زما مريد جوړېدل غواړى نو کۀ هغه د خپل مور، پلار، ښځې، بچو، وروڼو، خوېندو او د خپل ځان نه زړۀ صبر نۀ کړى نو هغه زما مريد جوړېدے نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24453, 'Luke 14:27', 'Luke', 14, 27, '&nbsp;او کوم سړے چې خپله سولۍ په خپله نۀ پورته کوى او په ما پسې نۀ راځى، هغه زما مريد جوړېدے نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24454, 'Luke 14:28', 'Luke', 14, 28, '&nbsp;ولې په تاسو کښې داسې څوک شته چې هغه يو برج جوړول غواړى او د مخکښې نه به د خرچې اندازه ونۀ لګوى چې په هغې يې سر ته رسولے شى او کۀ نه؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24455, 'Luke 14:29', 'Luke', 14, 29, '&nbsp;ګنې کۀ چرې هغۀ د دې بنيادونه اېښى وى او بيا يې سر ته نۀ شى رسولے نو ټول ليدونکى به ورپورې خندا ګانې کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24456, 'Luke 14:30', 'Luke', 14, 30, '&nbsp;هغوئ به وائى چې دۀ ته ګورئ چې کار يې شروع کړو او سر ته يې ونۀ رسولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24457, 'Luke 14:31', 'Luke', 14, 31, '&nbsp;يا کوم بادشاه به داسې وى چې هغه به د بل بادشاه سره د جنګېدو نه وړاندې دا اندازه نۀ لګوى چې د لسو زرو کسانو سره زۀ د هغه بادشاه مقابله کولے شم څوک چې د شلو زرو کسانو سره په ما حمله کوى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24458, 'Luke 14:32', 'Luke', 14, 32, '&nbsp;او کۀ هغه نۀ شى کولے نو د حملې کولو نه وړاندې به هغه خپله جرګه هغۀ ته ورولېږى او د صُلح د شرطُونو به ورنه خواست وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24459, 'Luke 14:33', 'Luke', 14, 33, '&nbsp;هم دغه شان تاسو کښې يو کس هم تر هغې زما مريد کېدے نۀ شى ترڅو چې هغۀ خپل ټول مال دولت ته شا کړې نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24460, 'Luke 14:34', 'Luke', 14, 34, '&nbsp;مالګه ښۀ څيز دے، خو کۀ مالګه بې‌خونده شى، نو بيا به څنګه مالګينه شى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24461, 'Luke 14:35', 'Luke', 14, 35, '&nbsp;بيا دا نۀ په زمکه او نۀ په ډيران پکاريږى، دا بس د عبث غورزولو ده. کۀ څوک د اورېدو غوږونه لرى نو هغوئ دې واورى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24462, 'Luke 15:1', 'Luke', 15, 1, '&nbsp;ټول محصولچيان او نور بدکاره خلق راغونډ وُو چې د عيسىٰ خبرې واورى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24463, 'Luke 15:2', 'Luke', 15, 2, '&nbsp;خو فريسيانو او د شرعې عالمانو په خپلو کښې غورېدل شروع کړل او داسې لګيا وُو، ”ګورئ دا سړے خو ګناهګارانو ته هرکلے وائى او ورسره خوراک هم کوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24464, 'Luke 15:3', 'Luke', 15, 3, '&nbsp;نو عيسىٰ ورته دا مِثال تير کړو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24465, 'Luke 15:4', 'Luke', 15, 4, '&nbsp;”کۀ چرې په تاسو کښې د يو تن سل ګډې وى او يوه ترېنه ورکه شى نو ولې هغه به دغه نورې يو کم سل تر هغې په تش مېدان پرې نۀ ږدى ترڅو چې يې هغه ورکه شوې موندلې نۀ وى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24466, 'Luke 15:5', 'Luke', 15, 5, '&nbsp;کله چې يې ومومى نو هغه به دا اوږو ته پورته کړى او خوشحالى به وکړى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24467, 'Luke 15:6', 'Luke', 15, 6, '&nbsp;او کله چې هغه کور ته واپس شى نو خپلو دوستانو او ګاونډيانو له به دعوت ورکړى او ورته به ووائى، ما سره زما په خوشحالۍ کښې شريک شئ. ځکه چې ما خپله ورکه شوې ګډه بيا وموندله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24468, 'Luke 15:7', 'Luke', 15, 7, '&nbsp;دغه شان زۀ تاسو ته وايم چې په آسمان کښې هم دا رنګ د يو ګناه ګار په توبه ګار کېدو بې‌حسابه خوشحالى کيږى، په نسبت د هغه يو کم سلو صادقانو چې د توبې حاجت نۀ لرى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24469, 'Luke 15:8', 'Luke', 15, 8, '&nbsp;يا دا چې کۀ د يوې ښځې سره لس د سپينو زرو سيکې وى او يوه ترېنه ورکه شى. ولې هغه به ډيوه نۀ بلوى، کور به نۀ جارُو کوى او د کور ګوټ ګوټ به تر هغې نۀ لټوى ترڅو چې يې هغه موندلې نۀ وى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24470, 'Luke 15:9', 'Luke', 15, 9, '&nbsp;نو کله چې يې ومومى نو هغه به خپلې ملګرې او ګاونډيانې راوبلى او ورته به ووائى چې ما سره خوشحالى وکړئ ځکه چې ما خپله ورکه شوې سيکه بيا وموندله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24471, 'Luke 15:10', 'Luke', 15, 10, '&nbsp;زۀ تاسو ته وايم چې د يو ګناه ګار په توبه کولو د خُدائ پاک په فرښتو کښې هم دغه شان خوشحالى کيږى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24472, 'Luke 15:11', 'Luke', 15, 11, '&nbsp;عيسىٰ بيا وفرمائيل چې، ”د يو سړى دوه زامن وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24473, 'Luke 15:12', 'Luke', 15, 12, '&nbsp;نو کشر خپل پلار ته ووئيل، پلاره، زما برخه جائيداد ما له راکړه. نو پلار خپل جائيداد په هغوئ تقسيم کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24474, 'Luke 15:13', 'Luke', 15, 13, '&nbsp;لږه موده پس هغه کشر زوئ خپل ټول جائيداد خرڅ کړو، پېسې يې پرې نغدې کړې او چرته لرې مُلک ته لاړو او هلته يې خپل مال په بدچلنۍ دوړه کړو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24475, 'Luke 15:14', 'Luke', 15, 14, '&nbsp;کله چې هغۀ هر څۀ خرچ کړل نو په هغه مُلک کښې سخت قحط راغلو او هغه ضرورتمند شو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24476, 'Luke 15:15', 'Luke', 15, 15, '&nbsp;نو بيا هغه په هم هغه مُلک کښې د يو زميندار سره نوکر شو نو زميندار هغه خپلو پټو ته ولېږلو چې خنزيرانو له د خوراک بندوبست وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24477, 'Luke 15:16', 'Luke', 15, 16, '&nbsp;د هغۀ ډېر زړۀ کېدو چې د هغه پوستکو نه ګېډه ډکه کړى کوم چې به خنزيرانو خوړل خو دۀ ته د دې اجازت نۀ وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24478, 'Luke 15:17', 'Luke', 15, 17, '&nbsp;خو کله چې د هغۀ عقل سر ته راغلو نو وې وئيل، زما د پلار ټولو نوکرانو سره د خپل ضرورت نه زيات خوراک شته او زۀ دلته د لوږې مرم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24479, 'Luke 15:18', 'Luke', 15, 18, '&nbsp;زۀ به لاړ شم خپل پلار ته به ووايم چې، پلاره، ما د خُدائ پاک او ستا خلاف ګناه کړې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24480, 'Luke 15:19', 'Luke', 15, 19, '&nbsp;نور زۀ د دې قابل نۀ يم چې زۀ ستا زوئ وګڼلے شم، نو ما خپل ځان سره نوکر کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24481, 'Luke 15:20', 'Luke', 15, 20, '&nbsp;نو په دې نيت هغه پاڅېدو او د خپل پلار کور طرف ته روان شو. خو هغه لا ډېر لرې وو چې د پلار پرې نظر شو نو زړۀ يې پرې درد وکړو او ورمنډه يې کړه او ورترغاړه وتو او ښکل يې کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24482, 'Luke 15:21', 'Luke', 15, 21, '&nbsp;خو زوئ ووئيل، پلاره، ما د خُدائ پاک او ستا خلاف ګناه کړې ده. د دې نه پس زۀ ستا د زوئ وئيلو قابل نۀ يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24483, 'Luke 15:22', 'Luke', 15, 22, '&nbsp;خو پلار يې خپلو نوکرانو ته ووئيل، زر شئ. زما د ټولو نه ښۀ چُوغه راوړئ او دۀ ته يې ورواغوندئ او ګوته ورپه لاس کړئ او څپلۍ ورپه پښو کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24484, 'Luke 15:23', 'Luke', 15, 23, '&nbsp;زمونږ هغه ښُکلے او څورب سخے راولئ او حلال يې کړئ او راځئ چې په شريکه خوشحالى وکړُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24485, 'Luke 15:24', 'Luke', 15, 24, '&nbsp;ځکه چې زما دا مړ زوئ بيا راژوندے شو، دے خو ورک شوے وو او بيا وموندے شو. او دغه شان هغوئ خوشحالى شروع کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24486, 'Luke 15:25', 'Luke', 15, 25, '&nbsp;نو په هم دې وخت کښې مشر زوئ يې په پټو کښې کار کولو کله چې کور ته واپس راروان شو نو په لار کښې د ساز او ګډا آوازونه د هغۀ تر غوږه شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24487, 'Luke 15:26', 'Luke', 15, 26, '&nbsp;هغۀ د خپل يو نوکر نه تپوس وکړو چې دا څۀ مېله ده؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24488, 'Luke 15:27', 'Luke', 15, 27, '&nbsp;نوکر ورته ووئيل، ستا ورور خپل کور ته راواپس شوے دے او ستا پلار هغۀ ته ښکلے سخے حلال کړو ځکه چې هغه يې روغ رمټ بيا موندلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24489, 'Luke 15:28', 'Luke', 15, 28, '&nbsp;خو مشر زوئ يې غصه شو او کور ته د ننوتو نه يې اِنکار وکړو. د هغۀ پلار بهر راغلو او ورته يې مِنت زارى وکړه چې دننه راځه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24490, 'Luke 15:29', 'Luke', 15, 29, '&nbsp;خو هغۀ ورته په جواب کښې ووئيل، دا دومره کالونه ما ستا لکه د غلام په شان تابعدارى کړې ده او کله مې هم ستا د حُکم نه مخ نۀ دے اړولے او تا ما له يو چېلے هم نۀ دے راکړے چې ما پرې خپلو دوستانو ته مېلمستيا کړے وے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24491, 'Luke 15:30', 'Luke', 15, 30, '&nbsp;خو چې اوس ستا دا زوئ راغلو چې ستا مال يې په کنجرو والوځولو نو تا هغۀ ته ښکلے سخے حلال کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24492, 'Luke 15:31', 'Luke', 15, 31, '&nbsp;نو پلار يې په جواب کښې ورته ووئيل، زما زويه، تۀ خو مدام ما سره يې او څۀ چې زما دى هغه ټول ستا دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24493, 'Luke 15:32', 'Luke', 15, 32, '&nbsp;نو مونږ ته ځکه خوشحالى او جشن کول په کار دى چې ستا دا مړ ورور اوس بيا راژوندے شو، دے خو ورک وو او مونږ بيا وموندلو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24494, 'Luke 16:1', 'Luke', 16, 1, '&nbsp;بيا عيسىٰ خپلو مريدانو ته وفرمائيل چې، ”يو دولتمند سړى ته د هغۀ د ناظر په سر چا شکايت وکړو چې هغه ستا مال الوځوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24495, 'Luke 16:2', 'Luke', 16, 2, '&nbsp;نو هغۀ هغه راوبللو او ورته يې ووئيل، دا ستا په حقله زۀ څۀ خبرې اورم؟ خپل حساب کِتاب راوړه ځکه چې د دې نه پس به تۀ زما ناظر نۀ يې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24496, 'Luke 16:3', 'Luke', 16, 3, '&nbsp;ناظر د ځان سره ووئيل، زما دا نېک چې مې د نوکرۍ نه وباسى نو اوس به زۀ څۀ کوم؟ زۀ خو دومره تکړه نۀ يم چې خټې لوټې وکړم او په خير غوښتلو هم شرمېږم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24497, 'Luke 16:4', 'Luke', 16, 4, '&nbsp;نو بيا اوس زۀ په دې پوهېږم چې څۀ وکړم. چې کله مې دے د نوکرۍ نه وباسى نو زما ډېر دوستان به زما مدد ته تيار وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24498, 'Luke 16:5', 'Luke', 16, 5, '&nbsp;هغۀ د خپل مالِک قرضدارى ځان ځان له راوبلل او اول کس ته يې ووئيل چې زما د مالِک په تا څومره قرض دے؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24499, 'Luke 16:6', 'Luke', 16, 6, '&nbsp;هغۀ جواب ورکړو، د زيتُونو تېل تقريباً درې زره ليټره. هغۀ ورته ووئيل چې خپل بِل دې واخله او زر کښېنه او څلور سوه يې وليکه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24500, 'Luke 16:7', 'Luke', 16, 7, '&nbsp;بيا يې بل ته ووئيل، او په تا څومره قرض پاتې دے؟ هغۀ ورته ووئيل، سل بورۍ غنم. هغۀ ورته ووئيل، خپل بِل دې واخله او اتيا بورۍ وليکه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');